import React, { Component } from 'react';
import axios from 'axios';
import '../css/RegisterComponent.css';

class RegisterComponent extends Component {
  constructor(props) {
    super(props);
    this.state = {
      txtPhone: '',
      txtUsername: '',
      txtPassword: '',
      txtConfirmPassword: '',
      txtEmail: ''
    };
  }

  btnRegisterClick = (e) => {
    e.preventDefault();
    const { txtPhone, txtUsername, txtPassword, txtConfirmPassword, txtEmail } = this.state;

    if (!txtPhone || !txtUsername || !txtPassword) {
      alert('Vui lòng nhập đầy đủ Số điện thoại, Tên đăng nhập và Mật khẩu!');
      return;
    }

    if (txtPassword !== txtConfirmPassword) {
      alert('Mật khẩu nhập lại không khớp!');
      return;
    }

    const newCustomer = {
      phone: txtPhone,
      username: txtUsername,
      password: txtPassword,
      email: txtEmail
    };

    axios.post('/api/customer/register', newCustomer)
      .then((res) => {
        const result = res.data;
        if (result.success) {
          alert('Đăng ký tài khoản thành công! Vui lòng đăng nhập.');
          window.location.href = '/login';
        } else {
          alert(result.message || 'Đăng ký thất bại!');
        }
      })
      .catch((err) => {
        console.error("Lỗi đăng ký:", err);
        alert('Có lỗi xảy ra khi kết nối đến máy chủ!');
      });
  };

  render() {
    return (
      <div className="register-container">
        <div className="register-header">
          <h2>Nhà hàng Văn Lang</h2>
          <p>Vietnamese Restaurant</p>
        </div>

        <div className="register-card">
          <h3>Đăng ký</h3>
          <form onSubmit={this.btnRegisterClick}>
            <div className="input-group">
              <input
                type="text"
                placeholder="Số điện thoại"
                value={this.state.txtPhone}
                onChange={(e) => this.setState({ txtPhone: e.target.value })}
              />
            </div>
            <div className="input-group">
              <input
                type="text"
                placeholder="Tên đăng nhập"
                value={this.state.txtUsername}
                onChange={(e) => this.setState({ txtUsername: e.target.value })}
              />
            </div>
            <div className="input-group">
              <input
                type="password"
                placeholder="Mật khẩu"
                value={this.state.txtPassword}
                onChange={(e) => this.setState({ txtPassword: e.target.value })}
              />
            </div>
            <div className="input-group">
              <input
                type="password"
                placeholder="Nhập lại mật khẩu"
                value={this.state.txtConfirmPassword}
                onChange={(e) => this.setState({ txtConfirmPassword: e.target.value })}
              />
            </div>
            <div className="input-group">
              <input
                type="email"
                placeholder="Email"
                value={this.state.txtEmail}
                onChange={(e) => this.setState({ txtEmail: e.target.value })}
              />
            </div>
            <button type="submit" className="btn-submit">Đăng ký</button>
          </form>

          <div className="switch-auth">
            Đã có tài khoản? <a href="/login">Đăng nhập</a>
          </div>
        </div>

        <div className="register-footer">
          <div>Nhà hàng Văn Lang</div>
          <div>© 2026</div>
        </div>
      </div>
    );
  }
}

export default RegisterComponent;
